65	@RestController
66	@CrossOrigin(exposedHeaders = "errors, content-type")
67	@RequestMapping("/api")
68	public class OwnerRestControllerV1 implements OwnersApi {
69	
70	    private final ClinicService clinicService;
71	
72	    private final OwnerMapper ownerMapper;
73	
74	    private final PetMapper petMapper;
75	
76	    private final VisitMapper visitMapper;
77	
78	    /**
79	     * Pattern for a syntactically valid email address: a non-empty local part, an {@code @},
80	     * and a domain containing at least one dot, with no whitespace in any segment.
81	     */
82	    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
83	
84	    /**
85	     * Maximum number of owners permitted in a single city. A create whose city already holds this many
86	     * owners (compared case-insensitively) is rejected with a 409 Conflict.
87	     */
88	    private static final int MAX_OWNERS_PER_CITY = 50;
89	
90	    /**
91	     * Maximum number of owners that may be registered on a single day (by registration date). A create
92	     * attempted once this many owners already carry today's registration date is rejected with a
93	     * 429 Too Many Requests.
94	     */
95	    private static final int MAX_OWNERS_PER_DAY = 100;
96	
97	    /**
98	     * Expansions of the common street-type abbreviations recognised by {@link #normalizeAddress}.
99	     * Keys and values are upper-case, matching the casing the address is folded to before expansion.
100	     */
101	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
102	        "ST", "STREET",
103	        "RD", "ROAD",
104	        "AVE", "AVENUE");
105	
106	    public OwnerRestControllerV1(ClinicService clinicService,
107	                                 OwnerMapper ownerMapper,
108	                                 PetMapper petMapper,
109	                                 VisitMapper visitMapper) {
110	        this.clinicService = clinicService;
111	        this.ownerMapper = ownerMapper;
112	        this.petMapper = petMapper;
113	        this.visitMapper = visitMapper;
114	    }
115	
116	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
117	    @Override
118	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
119	        Collection<Owner> owners;
120	        if (lastName != null) {
121	            owners = this.clinicService.findOwnerByLastName(lastName);
122	        } else {
123	            owners = this.clinicService.findAllOwners();
124	        }
125	        if (owners.isEmpty()) {
126	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
127	        }
128	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
129	    }
130	
131	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
132	    @Override
133	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
134	        Owner owner = this.clinicService.findOwnerById(ownerId);
135	        if (owner == null) {
136	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
137	        }
138	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
139	    }
140	
141	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
142	    @Override
143	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
144	        validateRequiredFields(ownerFieldsDto);
145	        HttpHeaders headers = new HttpHeaders();
146	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
147	        LocalDate registrationDate = Owner.resolveRegistrationDate(owner.getRegistrationDate());
148	        owner.setRegistrationDate(registrationDate);
149	        requireDailyCapacity(registrationDate);
150	        requireCityHasCapacity(owner.getCity());
151	        owner.setAddress(normalizeAddress(ownerFieldsDto.getAddress()));
152	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
153	            joinHousehold(owner);
154	        } else {
155	            requireUniqueHousehold(owner.getLastName(), owner.getAddress());
156	        }
157	        String telephone = normalizeTelephone(ownerFieldsDto.getTelephone());
158	        requireUniqueTelephone(telephone);
159	        owner.setTelephone(telephone);
160	        owner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
161	        owner.setCustomerCode(generateCustomerCode(owner.getCity(), owner.getLastName()));
162	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
163	        this.clinicService.saveOwner(owner);
164	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
165	        headers.setLocation(UriComponentsBuilder.newInstance()
166	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
167	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
168	    }
169	
170	    /**
171	     * Rejects a create once {@value #MAX_OWNERS_PER_DAY} or more owners already carry the new owner's
172	     * adjusted business-day registration date. Existing owners are counted by {@code registrationDate}
173	     * equal to that date, before the new owner is saved, so the count reflects only the owners that
174	     * existed prior to this create.
175	     *
176	     * @param registrationDate the new owner's effective registration date, already rolled forward onto
177	     *     a business day
178	     * @throws DailyOwnerLimitException if {@value #MAX_OWNERS_PER_DAY} or more owners are already
179	     *     registered on that business day
180	     */
181	    private void requireDailyCapacity(LocalDate registrationDate) {
182	        long dayOwnerCount = this.clinicService.findAllOwners().stream()
183	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
184	            .count();
185	        if (dayOwnerCount >= MAX_OWNERS_PER_DAY) {
186	            throw new DailyOwnerLimitException(registrationDate);
187	        }
188	    }
189	
190	    /**
191	     * Rejects an owner whose city already contains the maximum allowed number of owners
192	     * ({@value #MAX_OWNERS_PER_CITY}). Existing owners are counted by city compared case-insensitively,
193	     * before the new owner is saved, so the count reflects only the owners that existed prior to this
194	     * create.
195	     *
196	     * @param city the city of the owner being created
197	     * @throws CityOwnerLimitException if the city already holds {@value #MAX_OWNERS_PER_CITY} or more owners
198	     */
199	    private void requireCityHasCapacity(String city) {
200	        long cityOwnerCount = this.clinicService.findAllOwners().stream()
201	            .filter(existing -> equalsIgnoreCase(existing.getCity(), city))
202	            .count();
203	        if (cityOwnerCount >= MAX_OWNERS_PER_CITY) {
204	            throw new CityOwnerLimitException(city);
205	        }
206	    }
207	
208	    /**
209	     * Generates the customer code for a newly created owner, formatted
210	     * {@code '<CITY3>-<LAST3>-<NNNN>'}. {@code CITY3} is the upper-cased first three letters of the
211	     * city, {@code LAST3} the upper-cased first three letters of the last name, and {@code NNNN} a
212	     * per-city, 4-digit zero-padded sequence equal to one more than the number of owners already in
213	     * that city (e.g. {@code 'LON-SMI-0007'}).
214	     *
215	     * @param city the owner's city
216	     * @param lastName the owner's last name
217	     * @return the generated customer code
218	     */
219	    private String generateCustomerCode(String city, String lastName) {
220	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase(Locale.ROOT);
221	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(Locale.ROOT);
222	        int sequence = (int) this.clinicService.findAllOwners().stream()
223	            .filter(existing -> equalsIgnoreCase(existing.getCity(), city))
224	            .count() + 1;
225	        return String.format("%s-%s-%04d", city3, last3, sequence);
226	    }
227	
228	    /**
229	     * Counts the existing owners that already share the given first name and last name, compared
230	     * case-insensitively. This is evaluated before the new owner is saved, so it reflects only the
231	     * owners that existed prior to this create.
232	     *
233	     * @param firstName the first name of the owner being created
234	     * @param lastName the last name of the owner being created
235	     * @return the number of pre-existing namesakes
236	     */
237	    private int countNamesakes(String firstName, String lastName) {
238	        return (int) this.clinicService.findAllOwners().stream()
239	            .filter(existing -> equalsIgnoreCase(existing.getFirstName(), firstName)
240	                && equalsIgnoreCase(existing.getLastName(), lastName))
241	            .count();
242	    }
243	
244	    /**
245	     * Compares two possibly-{@code null} strings for equality, ignoring case. Two {@code null} values
246	     * are considered equal and a {@code null} is never equal to a non-{@code null} value.
247	     *
248	     * @param a the first value, possibly {@code null}
249	     * @param b the second value, possibly {@code null}
250	     * @return whether the values are equal ignoring case
251	     */
252	    private boolean equalsIgnoreCase(String a, String b) {
253	        return a == null ? b == null : a.equalsIgnoreCase(b);
254	    }
255	
256	    /**
257	     * Rejects an owner payload that is missing or blank in any required field. Bean Validation
258	     * (via {@code @Valid}) already rejects {@code null} values and fields that violate their size
259	     * or pattern constraints; this guard additionally rejects whitespace-only values for fields
260	     * (such as address and city) that have no pattern constraint, so that no required field is blank.
261	     *
262	     * @param ownerFieldsDto the submitted owner fields
263	     * @throws InvalidOwnerFieldsException if one or more required fields are missing or blank
264	     */
265	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
266	        List<String> invalidFields = new ArrayList<>();
267	        if (!StringUtils.hasText(ownerFieldsDto.getFirstName())) {
268	            invalidFields.add("firstName");
269	        }
270	        if (!StringUtils.hasText(ownerFieldsDto.getLastName())) {
271	            invalidFields.add("lastName");
272	        }
273	        if (!StringUtils.hasText(normalizeAddress(ownerFieldsDto.getAddress()))) {
274	            invalidFields.add("address");
275	        }
276	        if (!StringUtils.hasText(ownerFieldsDto.getCity())) {
277	            invalidFields.add("city");
278	        }
279	        if (!StringUtils.hasText(ownerFieldsDto.getTelephone())) {
280	            invalidFields.add("telephone");
281	        }
282	        if (!invalidFields.isEmpty()) {
283	            throw new InvalidOwnerFieldsException(invalidFields);
284	        }
285	    }
286	
287	    /**
288	     * Normalizes a submitted telephone number to E.164 form and requires the result to be valid. The
289	     * normalized E.164 string (a leading {@code '+'} followed by country code and national digits) is
290	     * what gets stored and returned.
291	     *
292	     * @param telephone the raw telephone value from the request
293	     * @return the normalized E.164 telephone number
294	     * @throws InvalidOwnerFieldsException if the value cannot form a valid E.164 number
295	     */
296	    private String normalizeTelephone(String telephone) {
297	        String e164 = toE164(telephone);
298	        if (e164 == null) {
299	            throw new InvalidOwnerFieldsException(List.of("telephone"));
300	        }
301	        return e164;
302	    }
303	
304	    /**
305	     * Converts a telephone value to E.164 form, giving the single authoritative definition of a
306	     * telephone's normalized form. Spaces, dashes and brackets are stripped. A leading {@code '+'}
307	     * and its country code are kept when present; otherwise country code {@code '+61'} is assumed and
308	     * a single leading {@code '0'} is dropped from the national digits. The result is valid only when
309	     * it contains 8 to 15 digits after the {@code '+'}.
310	     *
311	     * <p>Returns {@code null} rather than throwing when the value cannot form a valid E.164 number, so
312	     * it is safe to apply to already-stored (possibly legacy) values when comparing them.
313	     *
314	     * @param telephone the raw telephone value, possibly {@code null}
315	     * @return the E.164 string, or {@code null} if the value cannot form a valid E.164 number
316	     */
317	    private String toE164(String telephone) {
318	        if (telephone == null) {
319	            return null;
320	        }
321	        String cleaned = telephone.replaceAll("[ \\-()]", "");
322	        String digits;
323	        if (cleaned.startsWith("+")) {
324	            digits = cleaned.substring(1);
325	        } else {
326	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
327	            digits = "61" + national;
328	        }
329	        if (!digits.matches("[0-9]{8,15}")) {
330	            return null;
331	        }
332	        return "+" + digits;
333	    }
334	
335	    /**
336	     * Normalizes an optional owner email. An absent (null or blank) email is allowed and yields
337	     * {@code null}. When present, the value must be a syntactically valid address; it is then stored
338	     * and returned lower-cased.
339	     *
340	     * @param email the raw email value from the request, possibly {@code null}
341	     * @return the lower-cased email, or {@code null} when none was supplied
342	     * @throws InvalidOwnerFieldsException if a value is present but not a valid email address
343	     */
344	    private String normalizeEmail(String email) {
345	        if (!StringUtils.hasText(email)) {
346	            return null;
347	        }
348	        String trimmed = email.trim();
349	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
350	            throw new InvalidOwnerFieldsException(List.of("email"));
351	        }
352	        return trimmed.toLowerCase(Locale.ROOT);
353	    }
354	
355	    /**
356	     * Rejects a telephone number whose E.164 form is already used by an existing owner. This enforces
357	     * that no two owners share the same E.164 telephone. Existing values are compared by their E.164
358	     * form; a stored value that cannot form a valid E.164 number is compared as-is.
359	     *
360	     * @param telephone the normalized (E.164) telephone of the owner being created
361	     * @throws DuplicateTelephoneException if another owner already has this E.164 telephone
362	     */
363	    private void requireUniqueTelephone(String telephone) {
364	        boolean inUse = this.clinicService.findAllOwners().stream()
365	            .map(Owner::getTelephone)
366	            .filter(existing -> existing != null)
367	            .map(existing -> {
368	                String e164 = toE164(existing);
369	                return e164 != null ? e164 : existing;
370	            })
371	            .anyMatch(telephone::equals);
372	        if (inUse) {
373	            throw new DuplicateTelephoneException(telephone);
374	        }
375	    }
376	
377	    /**
378	     * Rejects an owner whose last name and address match those of an existing owner, where both are
379	     * compared case-insensitively and with runs of whitespace collapsed to a single space (a shared
380	     * household). The caller skips this check when the request opts in via {@code sharesHousehold}.
381	     *
382	     * @param lastName the last name of the owner being created
383	     * @param address the address of the owner being created
384	     * @throws DuplicateHouseholdException if another owner shares the same last name and address
385	     */
386	    private void requireUniqueHousehold(String lastName, String address) {
387	        if (!findHouseholdMembers(lastName, address).isEmpty()) {
388	            throw new DuplicateHouseholdException(lastName, address);
389	        }
390	    }
391	
392	    /**
393	     * Returns the existing owners that belong to the same household as the given last name and
394	     * address, i.e. those whose last name and address match case-insensitively and with runs of
395	     * whitespace collapsed to a single space.
396	     *
397	     * @param lastName the last name to match
398	     * @param address the address to match
399	     * @return the matching owners (possibly empty, never {@code null})
400	     */
401	    private List<Owner> findHouseholdMembers(String lastName, String address) {
402	        String normalizedLastName = normalizeForHousehold(lastName);
403	        String normalizedAddress = normalizeAddress(address);
404	        return this.clinicService.findAllOwners().stream()
405	            .filter(existing -> normalizeForHousehold(existing.getLastName()).equals(normalizedLastName)
406	                && normalizeAddress(existing.getAddress()).equals(normalizedAddress))
407	            .toList();
408	    }
409	
410	    /**
411	     * Joins the owner being created to the shared household of any existing owner(s) that have the
412	     * same last name and address (compared case-insensitively with collapsed whitespace). Every
413	     * member of the household - the existing owners and the new one - is assigned the same stable
414	     * {@code householdId}, so the shared identifier can be read back from any of them.
415	     *
416	     * <p>When no existing owner shares the household there is nobody to share an identifier with, so
417	     * the owner is left without a {@code householdId}.
418	     *
419	     * @param owner the owner being created, whose {@code householdId} is set when a household is joined
420	     */
421	    private void joinHousehold(Owner owner) {
422	        List<Owner> members = findHouseholdMembers(owner.getLastName(), owner.getAddress());
423	        if (members.isEmpty()) {
424	            return;
425	        }
426	        String householdId = computeHouseholdId(owner.getLastName(), owner.getAddress());
427	        owner.setHouseholdId(householdId);
428	        for (Owner member : members) {
429	            if (!householdId.equals(member.getHouseholdId())) {
430	                member.setHouseholdId(householdId);
431	                this.clinicService.saveOwner(member);
432	            }
433	        }
434	    }
435	
436	    /**
437	     * Computes the stable, shared household identifier for a last name and address. The value is
438	     * derived deterministically from the normalized (case-insensitive, whitespace-collapsed) last
439	     * name and address, so every owner in the same household computes the same identifier.
440	     *
441	     * @param lastName the last name of the household
442	     * @param address the address of the household
443	     * @return the household identifier, formatted {@code 'HH-<12 upper-case hex digits>'}
444	     */
445	    private String computeHouseholdId(String lastName, String address) {
446	        String key = normalizeForHousehold(lastName) + "\n" + normalizeAddress(address);
447	        try {
448	            byte[] digest = MessageDigest.getInstance("SHA-256")
449	                .digest(key.getBytes(StandardCharsets.UTF_8));
450	            StringBuilder hex = new StringBuilder();
451	            for (int i = 0; i < 6; i++) {
452	                hex.append(String.format("%02X", digest[i]));
453	            }
454	            return "HH-" + hex;
455	        } catch (NoSuchAlgorithmException e) {
456	            throw new IllegalStateException("SHA-256 algorithm not available", e);
457	        }
458	    }
459	
460	    /**
461	     * Normalizes a value for case-insensitive, whitespace-collapsed household comparison: leading and
462	     * trailing whitespace is trimmed, any internal run of whitespace is collapsed to a single space,
463	     * and the result is lower-cased. A {@code null} value normalizes to an empty string.
464	     *
465	     * @param value the raw value, possibly {@code null}
466	     * @return the normalized value
467	     */
468	    private String normalizeForHousehold(String value) {
469	        return collapseWhitespace(value).toLowerCase(Locale.ROOT);
470	    }
471	
472	    /**
473	     * Trims leading and trailing whitespace and collapses any internal run of whitespace to a single
474	     * space, giving the single definition of that step shared by the owner normalizers. A {@code null}
475	     * value yields an empty string.
476	     *
477	     * @param value the raw value, possibly {@code null}
478	     * @return the trimmed, whitespace-collapsed value
479	     */
480	    private String collapseWhitespace(String value) {
481	        if (value == null) {
482	            return "";
483	        }
484	        return value.trim().replaceAll("\\s+", " ");
485	    }
486	
487	    /**
488	     * Normalizes an owner's address to its canonical, stored-and-returned form: leading and trailing
489	     * whitespace is trimmed, any internal run of whitespace is collapsed to a single space, the result
490	     * is upper-cased, and common street-type abbreviations are expanded as whole words
491	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). A {@code null} or
492	     * blank-after-collapsing value normalizes to an empty string. The transformation is idempotent, so
493	     * applying it to an already-normalized (or legacy) value is safe when comparing addresses.
494	     *
495	     * @param address the raw address value, possibly {@code null}
496	     * @return the normalized address
497	     */
498	    private String normalizeAddress(String address) {
499	        String collapsed = collapseWhitespace(address).toUpperCase(Locale.ROOT);
500	        if (collapsed.isEmpty()) {
501	            return "";
502	        }
503	        String[] tokens = collapsed.split(" ");
504	        StringBuilder normalized = new StringBuilder();
505	        for (int i = 0; i < tokens.length; i++) {
506	            if (i > 0) {
507	                normalized.append(' ');
508	            }
509	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
510	        }
511	        return normalized.toString();
512	    }
513	
514	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
515	    @Override
516	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
517	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
518	        if (currentOwner == null) {
519	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
520	        }
521	        currentOwner.setAddress(ownerFieldsDto.getAddress());
522	        currentOwner.setCity(ownerFieldsDto.getCity());
523	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
524	        currentOwner.setLastName(ownerFieldsDto.getLastName());
525	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
526	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
527	        this.clinicService.saveOwner(currentOwner);
528	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
529	    }
530	
531	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
532	    @Transactional
533	    @Override
534	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
535	        Owner owner = this.clinicService.findOwnerById(ownerId);
536	        if (owner == null) {
537	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
538	        }
539	        this.clinicService.deleteOwner(owner);
540	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
541	    }
542	
543	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
544	    @Override
545	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
546	        Owner owner = this.clinicService.findOwnerById(ownerId);
547	        if (owner == null) {
548	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
549	        }
550	        HttpHeaders headers = new HttpHeaders();
551	        Pet pet = petMapper.toPet(petFieldsDto);
552	        owner.setId(ownerId);
553	        pet.setOwner(owner);
554	        pet.getType().setName(null);
555	        this.clinicService.savePet(pet);
556	        PetDto petDto = petMapper.toPetDto(pet);
557	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
558	            .buildAndExpand(pet.getId()).toUri());
559	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
560	    }
