562	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
563	    @Override
564	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
565	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
566	        if (currentOwner != null) {
567	            Pet currentPet = this.clinicService.findPetById(petId);
568	            if (currentPet != null) {
569	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
570	                currentPet.setName(petFieldsDto.getName());
571	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
572	                this.clinicService.savePet(currentPet);
573	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
574	            }
575	        }
576	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
577	    }
