579	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
580	    @Override
581	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
582	        HttpHeaders headers = new HttpHeaders();
583	        Visit visit = visitMapper.toVisit(visitFieldsDto);
584	        Pet pet = new Pet();
585	        pet.setId(petId);
586	        visit.setPet(pet);
