589	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
590	            .buildAndExpand(visit.getId()).toUri());
591	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
592	    }
