189	    /**
190	     * Resolves the effective registration date and rolls it onto a business day. An absent
191	     * ({@code null}) value defaults to the server's current date; a supplied value is used as-is.
192	     * The resulting date is then rolled forward so it never falls on a weekend: a Saturday or Sunday
193	     * becomes the following Monday, while any weekday is returned unchanged.
194	     *
195	     * <p>This is the single definition of both the defaulting and the business-day roll, used
196	     * wherever the effective registration date is needed - by the {@code @PrePersist} hook that
197	     * stamps the owner and by the create endpoint that counts owners per business day.
198	     *
199	     * @param supplied the registration date from the request, or {@code null} when none was supplied
200	     * @return the effective registration date, guaranteed to fall on a business day
201	     */
202	    public static LocalDate resolveRegistrationDate(LocalDate supplied) {
203	        LocalDate effective = supplied != null ? supplied : LocalDate.now();
204	        return switch (effective.getDayOfWeek()) {
205	            case SATURDAY -> effective.plusDays(2);
206	            case SUNDAY -> effective.plusDays(1);
207	            default -> effective;
208	        };
209	    }
